from typing import Any

import httpx
from fastmcp import FastMCP


def build_mcp_server(
    openapi_spec: dict[str, Any],
    client: httpx.AsyncClient,
    name: str = "OpenAPI Server",
) -> FastMCP:
    """Build an MCP server whose tools mirror the operations in an OpenAPI spec.

    Args:
        openapi_spec: Minimal OpenAPI 3.0 specification as a dict.
        client: httpx.AsyncClient pre-configured with the API base URL.
        name: Name for the resulting MCP server.

    Returns:
        A FastMCP server instance with one tool per OpenAPI operation.
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=name,
    )


if __name__ == "__main__":
    OPENAPI_SPEC: dict[str, Any] = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "paths": {
            "/items/{item_id}": {
                "get": {
                    "operationId": "get_item",
                    "parameters": [
                        {
                            "name": "item_id",
                            "in": "path",
                            "required": True,
                            "schema": {"type": "integer"},
                        }
                    ],
                    "responses": {"200": {"description": "OK"}},
                }
            }
        },
    }

    api_client = httpx.AsyncClient(base_url="https://api.example.com")
    mcp = build_mcp_server(OPENAPI_SPEC, api_client, name="Example API MCP Server")
